import os
import requests
from identity_models import PasswordResetRequest, PasswordResetResponse

def password_reset(request: PasswordResetRequest) -> PasswordResetResponse:
    domain = os.environ.get("AUTH0_DOMAIN")
    client_id = os.environ.get("AUTH0_CLIENT_ID")

    if not all([domain, client_id]):
        return PasswordResetResponse(
            message="Auth0 configuration missing. Please set AUTH0_DOMAIN and AUTH0_CLIENT_ID environment variables."
        )

    url = f"https://{domain}/dbconnections/change_password"
    headers = {'content-type': 'application/json'}
    payload = {
        'client_id': client_id,
        'email': request.email,
        'connection': os.environ.get("AUTH0_DATABASE_CONNECTION", "Username-Password-Authentication") # Default connection
    }

    try:
        response = requests.post(url, headers=headers, json=payload)
        response.raise_for_status()

        return PasswordResetResponse(
            message=f"Password reset email sent to {request.email}."
        )
    except requests.exceptions.HTTPError as e:
        return PasswordResetResponse(
            message=f"Password reset failed: {e}. Response: {e.response.text}"
        )
    except Exception as e:
        return PasswordResetResponse(
            message=f"An unexpected error occurred during password reset: {e}"
        )

import os
from google.cloud import language_v2 as language

def profile_moderation(text: str) -> dict:
    client = language.LanguageServiceClient()

    # Google Cloud Natural Language API requires GOOGLE_APPLICATION_CREDENTIALS to be set
    # or running in a Google Cloud environment.
    # For local development, ensure your environment is authenticated.

    document = language.Document(
        content=text, 
        type_=language.Document.Type.PLAIN_TEXT
    )

    try:
        # Perform content classification to identify potentially problematic content
        response = client.classify_text(request={'document': document})

        moderation_results = {
            "moderated": False,
            "categories": []
        }

        if response.categories:
            for category in response.categories:
                moderation_results["categories"].append({
                    "name": category.name,
                    "confidence": category.confidence
                })
                # Example: Flag if confidence is high for certain categories
                if category.confidence > 0.7 and ("/Politics" in category.name or "/Religion" in category.name or "/Sensitive Subjects" in category.name):
                    moderation_results["moderated"] = True

        return moderation_results
    except Exception as e:
        return {"moderated": False, "error": f"Moderation failed: {e}"}

import os
from google.cloud import firestore

def profile_note_store(user_id: str, notes: dict) -> dict:
    # Initialize Firestore client
    # Ensure GOOGLE_APPLICATION_CREDENTIALS is set or run in a Google Cloud environment
    db = firestore.Client()

    try:
        doc_ref = db.collection('onboarding_notes').document(user_id)
        doc_ref.set(notes, merge=True) # merge=True allows updating specific fields without overwriting the entire document
        return {"status": "success", "message": f"Notes for user {user_id} stored successfully."}
    except Exception as e:
        return {"status": "error", "message": f"Failed to store notes for user {user_id}: {e}"}
